import { useEffect, useState } from "react";
import UsersForm from "./UsersForm";

export default function UserRoleManagement() {
  const [usuarios, setUsuarios] = useState([]);

  const cargarUsuarios = async () => {
    const res = await fetch("http://localhost:3000/usuarios");
    const data = await res.json();
    setUsuarios(data);
  };

  useEffect(() => {
    cargarUsuarios();
  }, []);

  const cambiarRol = async (email) => {
    const usuario = usuarios.find(u => u.email === email);
    const nuevoRol = usuario.rol === "admin" ? "user" : "admin";

    await fetch(`http://localhost:3000/usuarios/${usuario.id}`, {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ rol: nuevoRol })
    });

    cargarUsuarios();
  };

  return (
    <div>
      <h2>Gestión de usuarios</h2>

      <UsersForm onAdd={cargarUsuarios} />

      <table className="table table-striped mt-4">
        <thead>
          <tr>
            <th>Email</th>
            <th>Rol</th>
            <th></th>
          </tr>
        </thead>
        <tbody>
          {usuarios.map(u => (
            <tr key={u.id}>
              <td>{u.email}</td>
              <td>{u.rol}</td>
              <td>
                <button className="btn btn-primary btn-sm" onClick={() => cambiarRol(u.email)}>
                  Cambiar rol
                </button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}
